{"version":3,"file":"NavHeader.jsdbx","sources":["../../___$insertStyle","../../src/client/components/shared/NavHeader.css","../../src/client/components/shared/NavHeader.tsx"],"sourcesContent":["export default function insertStyle(css, tagName = "style") {
    if (!css || typeof window === "undefined")
        return;
    if (tagName === "style") {
        const style = document.createElement("style");
        style.setAttribute("type", "text/css");
        style.innerHTML = css;
        document.head.appendChild(style);
    }
    else if (tagName === "link") {
        const link = document.createElement("link");
        link.setAttribute("rel", "stylesheet");
        link.setAttribute("href", css);
        document.head.appendChild(link);
    }
    return css;
}",".nav-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: #060911;
  border-bottom: 1px solid #1a2035;
  padding: 0 24px;
  height: 56px;
  position: sticky;
  top: 0;
  z-index: 100;
}

/* ─── Left: Logo + Wordmark + Pill ─── */
.nav-header__left {
  display: flex;
  align-items: center;
  gap: 10px;
}

.nav-header__logo-mark {
  display: flex;
  align-items: center;
  justify-content: center;
}

.nav-header__wordmark {
  font-size: 16px;
  font-weight: 700;
  color: #e2e8f0;
  letter-spacing: -0.3px;
}

.nav-header__pill {
  font-size: 10px;
  font-weight: 600;
  color: #64748b;
  letter-spacing: 0.8px;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid #1a2035;
  border-radius: 20px;
  padding: 3px 10px;
  text-transform: uppercase;
}

/* ─── Center: Nav Tabs ─── */
.nav-header__center {
  display: flex;
  align-items: center;
  gap: 2px;
}

.nav-header__tab {
  padding: 7px 16px;
  border-radius: 6px;
  font-size: 13px;
  font-weight: 500;
  color: #64748b;
  text-decoration: none;
  transition: color 0.15s ease, background 0.15s ease;
}

.nav-header__tab:hover {
  color: #cbd5e1;
}

.nav-header__tab--active {
  color: #ffffff;
  font-weight: 600;
  background: rgba(255, 255, 255, 0.07);
}

/* ─── Right: Search, Bell, Date, Avatar ─── */
.nav-header__right {
  display: flex;
  align-items: center;
  gap: 12px;
}

.nav-header__search {
  display: flex;
  align-items: center;
  gap: 8px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid #1a2035;
  border-radius: 8px;
  padding: 6px 12px;
}

.nav-header__search-icon {
  color: #64748b;
  flex-shrink: 0;
}

.nav-header__search-input {
  background: none;
  border: none;
  outline: none;
  color: #e2e8f0;
  font-size: 12px;
  width: 170px;
}

.nav-header__search-input::placeholder {
  color: #64748b;
}

.nav-header__bell {
  display: flex;
  align-items: center;
  justify-content: center;
  background: none;
  border: none;
  color: #64748b;
  cursor: pointer;
  padding: 6px;
  border-radius: 6px;
  position: relative;
  transition: color 0.15s ease;
}

.nav-header__bell:hover {
  color: #e2e8f0;
}

.nav-header__badge {
  position: absolute;
  top: 0;
  right: 0;
  background: #ef4444;
  color: #fff;
  font-size: 9px;
  font-weight: 700;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
}

.nav-header__date-pill {
  display: flex;
  align-items: center;
  gap: 6px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid #1a2035;
  border-radius: 20px;
  padding: 5px 12px;
  color: #94a3b8;
  font-size: 12px;
  cursor: pointer;
  transition: border-color 0.15s ease;
}

.nav-header__date-pill:hover {
  border-color: #334155;
}

.nav-header__avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: #3b82f6;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  font-weight: 700;
  color: #fff;
  letter-spacing: 0.5px;
}
","import React, { useState } from 'react';
import './NavHeader.css';

const NAV_TABS = [
  { label: 'Executive', href: '/x_2145749_qc_exec_dashboard.do' },
  { label: 'Operations', href: '/x_2145749_qc_ops_dashboard.do' },
  { label: 'Dark Store', href: '/x_2145749_qc_dark_store_dashboard.do' },
  { label: 'Fraud', href: '/x_2145749_qc_fraud_dashboard.do' },
];

function NavHeader() {
  const currentPath = window.location.pathname;
  const [searchValue, setSearchValue] = useState('');

  const handleSearchKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter' && searchValue.trim()) {
      const storeId = searchValue.trim();
      window.location.href = `/x_2145749_qc_dark_store_dashboard.do?store=DS-${storeId}`;
    }
  };

  return (
    <header className="nav-header">
      <div className="nav-header__left">
        <div className="nav-header__logo-mark">
          <svg width="24" height="24" viewBox="0 0 24 24" fill="none">
            <rect width="24" height="24" rx="6" fill="#3b82f6" />
            <path d="M7 8h10M7 12h7M7 16h10" stroke="#fff" strokeWidth="2" strokeLinecap="round" />
          </svg>
        </div>
        <span className="nav-header__wordmark">DarkOps</span>
        <span className="nav-header__pill">OPERATIONAL INTELLIGENCE</span>
      </div>

      <nav className="nav-header__center">
        {NAV_TABS.map((tab) => {
          const isActive = currentPath.includes(tab.href.replace('.do', '').replace('/', ''));
          return (
            <a
              key={tab.label}
              href={tab.href}
              className={`nav-header__tab ${isActive ? 'nav-header__tab--active' : ''}`}
            >
              {tab.label}
            </a>
          );
        })}
      </nav>

      <div className="nav-header__right">
        <div className="nav-header__search">
          <svg className="nav-header__search-icon" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
            <circle cx="11" cy="11" r="8" />
            <path d="M21 21l-4.35-4.35" />
          </svg>
          <input
            type="text"
            placeholder="Search store ID e.g. 1462..."
            className="nav-header__search-input"
            value={searchValue}
            onChange={(e) => setSearchValue(e.target.value)}
            onKeyDown={handleSearchKeyDown}
          />
        </div>

        <button className="nav-header__bell" aria-label="Notifications">
          <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
            <path d="M18 8A6 6 0 0 0 6 8c0 7-3 9-3 9h18s-3-2-3-9" />
            <path d="M13.73 21a2 2 0 0 1-3.46 0" />
          </svg>
          <span className="nav-header__badge">5</span>
        </button>

        <button className="nav-header__date-pill">
          <span>Last 30 days</span>
          <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5">
            <path d="M6 9l6 6 6-6" />
          </svg>
        </button>

        <div className="nav-header__avatar">AK</div>
      </div>
    </header>
  );
}

export default NavHeader;
